<script setup lang="ts">
import {computed,ref} from 'vue'
import {useStudio} from './studioContext'
import AppIcon from './AppIcon.vue'
import {organizeMaterials} from './materialOrganize'
const props=defineProps<{page:string,target?:string,task?:string}>(),s=useStudio(),working=ref(false),choosing=ref(false),selected=ref<string[]>([])
const info=computed(()=>s.checklist.value.pages?.find((p:any)=>p.id===props.page)),job=computed(()=>s.p.value?.workspace.jobs?.find((j:any)=>j.family==='generation'&&j.scope===props.page))
const targets=computed(()=>s.entries(({characters:'persona',outline:'plot',clues:'clue',storyboards:'storyboard'} as any)[props.page]||'material'))
const hasMissing=computed(()=>!info.value?.complete||info.value?.done<info.value?.total)
async function launch(){if(props.page==='library'){working.value=true;try{await organizeMaterials(s)}catch(e:any){s.error.value=e.message}finally{working.value=false}return}if(!hasMissing.value){choosing.value=!choosing.value;return}void s.generateStep(props.page,props.target?[props.target]:[],!hasMissing.value,props.task)}
const label=computed(()=>({library:'整理资料',outline:'生成剧本大纲',clues:'整理线索',characters:'生成人物对话设定',storyboards:'生成分镜提示词'} as any)[props.page])
// Failure text sits under the buttons in red; a step blocker (why generating is disabled) uses the same slot in a muted tone.
const failedJob=computed(()=>job.value&&['failed','interrupted','partial'].includes(job.value.state)?job.value:null)
const hint=computed(()=>failedJob.value?(failedJob.value.error||'部分结果供你选择，其他内容可继续使用'):props.page!=='library'&&info.value?.canGenerate===false?(info.value?.blocker||''):'')
const hintIsError=computed(()=>!!failedJob.value&&(failedJob.value.state!=='partial'||!!failedJob.value.error))
async function control(action:string){working.value=true;try{await s.api(`/projects/${s.p.value.id}/studio/generation-batches/${job.value.id}/${action}`,'POST',{version:s.p.value.version,requestId:crypto.randomUUID()});await s.syncLatest()}catch(e:any){s.error.value=e.message}finally{working.value=false}}
</script>
<template><div class="generation-control"><div class="generation-actions"><button class="primary" :disabled="working||s.generating.value||!s.p.value||(page!=='library'&&info?.canGenerate===false)" :title="info?.blocker||''" @click="launch"><AppIcon name="ai" :size="15"/>{{page==='library'?'整理资料':!hasMissing?'选择重新生成':info?.done?'生成未完成内容':label}}<small v-if="page!=='library'">{{!hasMissing?'重新生成':info?.done?'补充生成':'首次生成'}}</small></button><template v-if="job"><span v-if="['queued','running'].includes(job.state)" role="status">{{job.progress}} · {{job.steps.filter((v:any)=>v.state==='completed').length}}/{{job.steps.length}}</span><button v-if="['queued','running'].includes(job.state)" @click="control('cancel')">取消任务</button><button v-else-if="failedJob" :disabled="working||s.generating.value" @click="control('continue')">继续未完成项</button></template></div><small v-if="hint" class="generation-hint" :class="{error:hintIsError}" :role="hintIsError?'alert':undefined">{{hint}}</small><div v-if="choosing" class="regeneration-selection"><label v-for="item in targets"><input type="checkbox" :value="item.id" v-model="selected">{{s.title(item)}}</label><button :disabled="!selected.length||s.generating.value" @click="s.generateStep(page,selected,true);choosing=false"><AppIcon name="ai" :size="14"/>重新生成选中内容</button></div></div></template>
<style scoped>.generation-control{display:flex;flex-direction:column;align-items:flex-end;gap:6px}.generation-actions{display:flex;align-items:center;justify-content:flex-end;gap:10px;flex-wrap:wrap}.generation-control .primary{display:flex;align-items:center;gap:7px}.generation-control .primary svg{color:#ebca72}.generation-control small,.generation-control .generation-actions>span{font-size:14px;color:#5d6b66}.generation-control .primary small{color:#dbe6e1;font-size:10px}.generation-hint{max-width:min(360px,100%);line-height:1.6;text-align:right;overflow-wrap:anywhere}.generation-control .generation-hint.error{color:#c0392b}@media(max-width:760px){.generation-control .primary{white-space:nowrap;padding:9px 11px;font-size:11px}.generation-control .primary small{display:none}}</style>
